(function(root){'use strict';
if(!root.FolioSpellOrganizer && typeof require==='function')root.FolioSpellOrganizer=require('./spell-organizer.js');
if(!root.FolioSpellOrganizerUI && typeof require==='function')root.FolioSpellOrganizerUI=require('./spell-organizer-ui.js');
const D=root.PipData,C=root.PipCore;
const escapeHtml=(s)=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const attr=escapeHtml;
const area=(s)=>escapeHtml(s).replace(/\n/g,'<br>');
const fmt=C.signed;
function icon(name){const paths={
 book:'<path d="M2 4h8a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H2zM22 4h-8a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h8z"/>',
 sword:'<path d="m6 18 12-12M4 20l4-4M14 4l6 6M3 21l4-4M13 3l8 8"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 feather:'<path d="M20 4C11 3 5 10 5 19c6-1 16-7 15-15ZM4 21c3-6 8-10 14-13"/>',
 moon:'<path d="M20 16a8 8 0 0 1-12-12 9 9 0 1 0 12 12Z"/>',
 dice:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><circle cx="16" cy="8" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="8" cy="16" r="1"/><circle cx="16" cy="16" r="1"/>',
 shield:'<path d="m12 2 9 4v7c0 5-4 8-9 9-5-1-9-4-9-9V6z"/>',
 spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 bag:'<path d="M6 9h12l3 12H3zM9 9V5a3 3 0 0 1 6 0v4"/>',
 undo:'<path d="M9 14 4 9l5-5M4 9h9a7 7 0 1 1-6.2 10"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 close:'<path d="M5 5l14 14M19 5 5 19"/>',
 settings:'<path d="M12 2v3m0 14v3M4.9 4.9 7 7m10 10 2.1 2.1M2 12h3m14 0h3M4.9 19.1 7 17M17 7l2.1-2.1"/><circle cx="12" cy="12" r="4"/>',
 scroll:'<path d="M6 3h12v16a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Zm0 0a3 3 0 0 0 0 6h10"/>',
 printer:'<path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 15h12v7H6z"/><path d="M17 12h1"/>'};
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.spark)+'</svg>';}
function panel(title,inside,extra='',opts=''){return `<section class="folio-panel ${opts}"><div class="panel-heading"><span class="panel-title">${title}</span>${extra}</div><div class="panel-body">${inside}</div></section>`;}
function pips(key,remaining,total){return `<div class="pip-set" role="group" aria-label="${attr(key)} ${remaining} of ${total} remaining">${Array.from({length:total},(_,i)=>`<span class="pip ${i<remaining?'filled':''}"></span>`).join('')}</div>`;}
function resourceRow(name,key,r,max,small=''){return `<div class="resource-row"><div class="resource-name"><strong>${name}</strong>${small?`<small>${small}</small>`:''}</div><div class="resource-controls">${max<=8?pips(name,r[key],max):`<span class="resource-number">${r[key]} / ${max}</span>`}<button class="stepper" aria-label="Spend ${name}" data-action="resource" data-key="${key}" data-delta="-1" data-max="${max}">−</button><button class="stepper" aria-label="Restore ${name}" data-action="resource" data-key="${key}" data-delta="1" data-max="${max}">+</button></div></div>`;}
function nav(active){return ['sheet','combat','spellbook','inventory','journal'].map((tab,i)=>`<button class="nav-link ${active===tab?'active':''}" data-action="nav" data-tab="${tab}" aria-current="${active===tab?'page':'false'}"><span class="nav-symbol">${['◈','⚔','✧','◇','✦'][i]}</span>${tab==='spellbook'?'Spellbook':tab.charAt(0).toUpperCase()+tab.slice(1)}</button>`).join('');}
function titleHeader(s){const character=s.character,art=root.FolioArtwork.sourceForEmblem(root.FolioActiveArtwork);return `<div class="identity-area"><img src="${attr(art)}" class="bookplate" alt="Character bookplate"/><div class="identity-copy"><div class="overline">Character folio · Level ${character.level}</div><h1>${escapeHtml(character.name)} ${character.fullName&&character.fullName!==character.name?`<span class="name-tail">/ ${escapeHtml(character.fullName)}</span>`:''}</h1><div class="identity-info">${escapeHtml(character.className)} ${character.level} <span>·</span> ${escapeHtml(character.subclass)} <span>·</span> ${escapeHtml(character.species)} <span>·</span> ${escapeHtml(character.background)}</div><p>${escapeHtml(character.tagline||'')}</p></div><div class="head-ornament" aria-hidden="true"><span>✦</span><span>◈</span><span>✦</span></div></div>`;}
function topbar(tab,canUndo,s){return `<div class="topbar"><button type="button" class="brand brand-home-button" data-action="go-library" aria-label="Return to character library" title="Return to character library"><img src="assets/folio-book.svg" alt=""/><span class="brand-copy"><span class="brand-name">THE FOLIO</span><span class="brand-sub">CHARACTER SHEET</span></span></button><nav class="primary-nav" aria-label="Main navigation">${nav(tab)}</nav><div class="top-actions"><details class="folio-options-menu"><summary class="quiet-button" aria-label="Character options">${icon('settings')}<span>Options</span><b aria-hidden="true">⌄</b></summary><div class="folio-options-list" role="group" aria-label="Character options"><button data-action="open-artwork">${icon('spark')} Artwork & tokens</button><button data-action="open-appearance">${icon('settings')} Appearance</button><button data-action="open-features">${icon('spark')} Features & traits</button><button data-action="edit-character">${icon('settings')} Edit character</button><button data-action="backup">${icon('scroll')} Backup</button><button data-action="print">${icon('printer')} Print</button></div></details><button class="quiet-button always-visible-undo" data-action="undo" ${canUndo?'':'disabled'} title="Undo the last change">${icon('undo')}<span>Undo</span></button></div></div>`;}
function damageModal(s,ui){const r=s.resources,c=s.character;
 const defenses=['Rogue','Monk'].includes(c.build?.characterClass)&&c.level>=(c.build?.characterClass==='Monk'?3:5);
 const defenseOptions=defenses?`<div class="damage-field"><label for="damage-defense">Special defense</label><select id="damage-defense"><option value="none">None · resolve normally</option>${c.build.characterClass==='Rogue'&&c.level>=5?`<option value="uncanny-dodge" ${ui?.damageDefense==='uncanny-dodge'?'selected':''}>Uncanny Dodge · Reaction</option>`:''}${c.build.characterClass==='Monk'&&c.level>=3?`<option value="deflect-attacks" ${ui?.damageDefense==='deflect-attacks'?'selected':''}>Deflect Attacks · Reaction</option>`:''}${c.level>=7?`<option value="evasion-success" ${ui?.damageDefense==='evasion-success'?'selected':''}>Evasion · successful DEX save</option><option value="evasion-fail" ${ui?.damageDefense==='evasion-fail'?'selected':''}>Evasion · failed DEX save</option>`:''}</select></div>`:'';
 const undying=c.templateKind==='starter'&&root.FolioClassMechanics?.ancients(c)&&c.level>=15&&(r.classResources?.['undying-sentinel']??1)>0;
 const barbarian=c.templateKind==='starter'&&c.build?.characterClass==='Barbarian'&&c.level>=11&&r.classState?.raging;
 const orc=c.templateKind==='starter'&&root.FolioSpecies2024?.id(c)==='orc'&&root.FolioSpecies2024?.charge(c,r,'endurance')>0;
 const lastStand=root.FolioFeat2024?.has(c,'Boon of Recovery')&&root.FolioFeat2024.remaining(c,r,'recovery-last-stand')>0;
 const heavyArmor=root.FolioFeat2024?.has(c,'Heavy Armor Master')&&(s.inventory?.items||[]).some(i=>i.equipped&&i.category==='armor'&&i.armor?.kind==='heavy');
 return `<div class="modal-scrim" data-action="close-modal"><section class="dialog form-dialog damage-dialog" role="dialog" aria-modal="true" aria-labelledby="damage-dialog-title"><button class="close-modal" data-action="close-modal" aria-label="Close damage options">×</button><span class="eyebrow">COMBAT · INCOMING DAMAGE</span><h2 id="damage-dialog-title">Apply damage</h2><p class="damage-intro">Record the amount your character was dealt. Select only modifiers that apply to <strong>this hit</strong>.</p><div class="damage-main-fields"><label class="damage-field"><span>Damage received</span><input id="damage-amount" type="number" min="1" step="1" inputmode="numeric" value="${attr(ui?.hpAmount??'5')}"/></label><label class="damage-field" for="damage-type"><span>Damage type</span><select id="damage-type" aria-label="Incoming damage type">${(root.FolioClassMechanics?.DAMAGE_TYPES||['Unspecified']).map(t=>`<option value="${attr(t)}" ${ui?.damageType===t?'selected':''}>${escapeHtml(t)}</option>`).join('')}</select></label></div><fieldset class="damage-modifiers"><legend>Adjust for this hit</legend><div class="damage-tiles"><label class="damage-tile"><input type="checkbox" id="damage-resistant" ${ui?.damageResistance?'checked':''}/><span><strong>Resistance</strong><small>Half damage</small></span></label><label class="damage-tile"><input type="checkbox" id="damage-vulnerable" ${ui?.damageVulnerability?'checked':''}/><span><strong>Vulnerability</strong><small>Double damage</small></span></label><label class="damage-tile"><input type="checkbox" id="damage-immune" ${ui?.damageImmunity?'checked':''}/><span><strong>Immunity</strong><small>No damage</small></span></label></div><p class="damage-hint">Supported species and class resistances apply automatically. Use these checks only for additional situational effects.</p></fieldset>${defenseOptions||undying||barbarian||orc||lastStand||heavyArmor?`<fieldset class="damage-modifiers damage-special"><legend>Defensive features</legend>${defenseOptions}${undying?'<label class="damage-feature"><input type="checkbox" id="damage-undying"><span>Undying Sentinel <small>Use only when the attack would reduce you to 0 HP without killing outright.</small></span></label>':''}${barbarian?'<label class="damage-feature"><input type="checkbox" id="damage-relentless" checked><span>Relentless Rage <small>Roll the qualifying save if this hit drops you to 0 HP.</small></span></label>':''}${orc?'<label class="damage-feature"><input type="checkbox" id="damage-orc-endurance"><span>Relentless Endurance · Orc <small>Stay at 1 HP on a qualifying nonfatal 0-HP hit. Once per Long Rest.</small></span></label>':''}${lastStand?'<label class="damage-feature"><input type="checkbox" id="damage-feat-last-stand"><span>Boon of Recovery · Last Stand <small>Once per Long Rest if confirmed damage would reduce you to 0 HP.</small></span></label>':''}${heavyArmor?'<label class="damage-feature"><input type="checkbox" id="damage-heavy-armor-attack"><span>Heavy Armor Master <small>Check only for an attack dealing Bludgeoning, Piercing or Slashing damage while wearing Heavy armor.</small></span></label>':''}</fieldset>`:''}<div class="damage-explainer"><strong>Order of operations</strong><p>Apply defenses, then Resistance, then Vulnerability. Immunity prevents damage. Temporary HP absorbs the remaining damage first.</p></div><div class="dialog-footer"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn danger" data-action="damage-apply">Apply damage</button></div></section></div>`;
}
function vitals(s,derived,ui){const r=s.resources;return `<section class="vitals" aria-label="Current combat values"><div class="ac-crest"><div class="crest-label">ARMOR CLASS</div><strong data-action="math" data-math="ac" role="button" tabindex="0" title="Show AC calculation">${derived.ac}</strong><span>${derived.armorDescription.startsWith('Genie')||derived.armorDescription.startsWith('Unarmored')?'UNARMORED':'EQUIPPED'}</span></div><div class="hp-vital"><div class="vital-label">${icon('heart')} HIT POINTS</div><div class="hp-display"><span class="hp-current">${r.hp}</span><span class="hp-divisor"> / ${r.maxHp}</span><span class="temp-pill">TEMP ${r.tempHp}</span></div><div class="hp-track"><span style="width:${r.maxHp?Math.max(0,Math.min(100,r.hp/r.maxHp*100)):0}%"></span></div><div class="hp-tools"><label class="sr-only" for="hp-amount">Amount for damage, healing or temporary HP</label><input id="hp-amount" type="number" min="0" step="1" value="${attr(ui?.hpAmount??'5')}" inputmode="numeric" aria-describedby="hp-help"/><button class="btn danger" data-action="damage" aria-label="Open damage options for the amount entered">− Damage</button><button class="btn heal" data-action="heal" aria-label="Heal using the amount entered">+ Heal</button><button class="btn secondary hp-temp-action" data-action="temp-hp" aria-label="Set temporary hit points using the amount entered">Set Temp HP</button></div>${r.lastDamage?`<span id="hp-help" class="hp-help">Last hit: ${escapeHtml(r.lastDamage.raw)} ${escapeHtml(r.lastDamage.type)} → ${escapeHtml(r.lastDamage.resolved)} taken (${escapeHtml(r.lastDamage.absorbed)} absorbed by temporary HP, ${escapeHtml(r.lastDamage.hpLost)} HP lost).</span>`:'<span id="hp-help" class="hp-help">Damage modifiers are set in the damage dialog.</span>'}</div><div class="vital-stat"><span>INITIATIVE</span><button data-action="math" data-math="initiative" class="stat-value">${fmt(derived.initiative)}</button></div><div class="vital-stat"><span>SPEED</span><strong>${derived.speed}<small> ft</small></strong></div><div class="vital-stat"><span>PROFICIENCY</span><button data-action="math" data-math="pb" class="stat-value">${fmt(derived.pb)}</button></div><div class="vital-stat"><span>SPELL DC</span>${s.character.templateKind==='starter'&&s.character.build?.slotMax?.every(x=>x===0)?'<strong title="No spell slots at this class level">—</strong>':`<button data-action="math" data-math="dc" class="stat-value">${derived.spellDC}</button>`}</div></section>`;}
function abilityCard(s,d,ui){return panel(`${icon('spark')} Ability Scores`,Object.entries(s.character.scores).map(([k,v])=>ui.editScore===k?`<form class="ability-row score-inline" id="score-form" data-score="${k}"><label class="ability-label" for="inline-${k}">${k.toUpperCase()}</label><input id="inline-${k}" name="score" type="number" min="1" max="30" inputmode="numeric" required value="${v}"/><button type="submit" title="Save ${k.toUpperCase()}">✓</button><button type="button" data-action="score-cancel" title="Cancel">×</button></form>`:`<div class="ability-row"><button class="score-trigger" data-action="score-edit" data-id="${k}" aria-label="Edit ${k.toUpperCase()} score, currently ${v}" title="Edit ${k.toUpperCase()} score"><span class="ability-label">${k.toUpperCase()}</span><span class="ability-score">${v}</span><span class="edit-pencil" aria-hidden="true">✎</span></button><button class="ability-mod" data-action="math" data-math="${k}" title="Explain ${k.toUpperCase()} modifier">${fmt(C.mod(v))}</button></div>`).join(''),'<span class="subtle-mini">CLICK SCORE TO EDIT</span>','abilities-panel');}
function savesCard(s,d){return panel(`${icon('shield')} Saving Throws`,Object.entries(s.character.scores).map(([k,v])=>{const prof=s.character.profSaves.includes(k);return `<div class="save-row"><span class="mark ${prof?'marked':''}">${prof?'◆':'◇'}</span><span>${k.toUpperCase()} ${prof?'<small>proficient</small>':''}</span><strong>${fmt(d.saves[k])}</strong>${s.character.templateKind==='starter'?'':`<span class="aura-number">${fmt(d.saves[k]+d.aura)} <i>in aura</i></span>`}</div>`;}).join('')+`${s.character.templateKind==='starter'?'':`<div class="micro-note">Aura of Protection adds ${fmt(d.aura)} to each save while active, including concentration.</div>`}`,s.character.templateKind==='starter'?'<span class="subtle-mini">PROFICIENCY</span>':'<span class="subtle-mini">BASE / IN AURA</span>');}
function skillsCard(s,d){return panel(`${icon('feather')} Skills`,D.skills.map(([name,ability])=>{const prof=s.character.profSkills.includes(name);const expert=s.character.expertise.includes(name);return `<div class="skill-row"><span class="mark ${prof?'marked':''}">${expert?'✦':prof?'◆':'◇'}</span><span>${name} <small>(${ability.toUpperCase()})</small></span><strong>${fmt(d.skills[name])}</strong></div>`;}).join('')+`<div class="micro-note">◆ proficient · ✦ expertise &nbsp; | &nbsp; Passive Perception ${10+d.skills.Perception}</div>`,'<span class="subtle-mini">PROFICIENCY VISIBLE</span>','skills-panel');}
function attacksCard(s,d){const I=root.PipInventory,ready=I.readyWeapons(s.inventory),nick=I.hasNickTwinBlades(s.inventory);return panel(`${icon('sword')} Weapons & Attacks`, `<div class="attack-table" role="table" aria-label="Weapon attacks"><div class="attack-head" role="row"><span>WEAPON</span><span>TO HIT</span><span>DAMAGE</span><span>MASTERY</span></div>${ready.map(item=>{const w=item.weapon||{},n=I.weaponNumbers(item,s.character,d);return `<button role="row" class="attack-row" data-action="reference" data-id="${attr(item.id)}"><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(w.range||'—')} · ${escapeHtml(w.properties||'')}</small></span><b>${fmt(n.attack)}</b><span><strong>${escapeHtml(w.damage||'—')}${n.damage>=0?'+':''}${n.damage}</strong><small>${escapeHtml(w.type||'')}</small></span><span class="mastery">${escapeHtml(w.mastery||'—')}</span></button>`;}).join('')||'<p class="note-hint">No weapons ready. Equip a weapon in Inventory.</p>'}</div><div class="information-strip"><span>Attack action:</span><strong>${s.character.templateKind==='starter'?'Weapon attacks available in Inventory':nick?'2 attacks + 1 Nick attack':'2 attacks (Extra Attack)'}</strong><span class="info-tag">${s.character.templateKind==='starter'?'Optional attack roller':nick?'Nick ready':'Review Light attacks'}</span></div><p class="note-hint">Weapon bonuses use the equipped weapon and active item effects. <button class="link-button" data-action="nav" data-tab="inventory">Manage weapons</button></p>`,'<span class="subtle-mini">PHYSICAL DICE FRIENDLY</span>');}
function featureCard(s){return panel(`${icon('spark')} Features & Traits`,root.PipCharacter.featureList(s.character).map(f=>`<button class="feature-row" data-action="reference" data-id="${f.id}"><div><strong>${escapeHtml(f.name)}</strong><small>${escapeHtml(f.short)}</small></div><span class="feature-tag">${escapeHtml(f.group)}</span><span class="chevron">›</span></button>`).join(''),'<button class="text-action" data-action="open-features">View and edit all</button>');}
function resourcesCard(s){if(s.character.templateKind==='starter')return panel(`${icon('book')} Resources`,resourceRow('Hit Dice (d'+(s.character.build?.hitDie||8)+')','hitDice',s.resources,s.character.level,'Track spent dice')+root.FolioBuilderUI.slotTracker(s)+root.FolioBuilderUI.classTracker(s)+root.PipCharacterUI.inlineResources(s)+`<div class="rest-actions"><button class="btn secondary" data-action="short-rest">Short rest</button><button class="btn secondary" data-action="long-rest">Long rest</button></div><p class="note-hint">Add class-specific resources in Features. Class spell lists, preparation limits, and slot spending are supported. Homebrew and supplementary features remain editable.</p>`);const r=s.resources,caps=root.PipCharacter.resourceCaps(s.character.level);return panel(`${icon('book')} Resources & Spell Slots`,resourceRow('1st-level slots','slots1',r,caps.slots1,'Long Rest')+resourceRow('2nd-level slots','slots2',r,caps.slots2,'Long Rest')+resourceRow('Channel Divinity','channelDivinity',r,caps.channelDivinity,'1 use / Short Rest')+resourceRow('Lay on Hands','layOnHands',r,caps.layOnHands,'HP pool')+`<div class="free-uses"><div class="minor-heading">FREE CASTS · LONG REST</div>${resourceRow('Divine Smite','freeDivineSmite',r,1)}${resourceRow('Find Steed','freeFindSteed',r,1)}${resourceRow('Hunter’s Mark','freeHuntersMark',r,1)}${resourceRow('Misty Step','freeMistyStep',r,1)}</div>`+resourceRow('Hit Dice (d10)','hitDice',r,caps.hitDice,'Track spent dice')+root.PipCharacterUI.inlineResources(s)+`<div class="rest-actions"><button class="btn secondary" data-action="short-rest">Short rest</button><button class="btn secondary" data-action="long-rest">Long rest</button></div><p class="note-hint">Rest controls restore listed features; spending Hit Dice during a Short Rest is tracked manually; a 2024 Long Rest restores spent Hit Dice.</p>`,'<span class="subtle-mini">TAP − TO SPEND / + TO RESTORE</span>');}
function conditionsCard(s){const r=s.resources;const labels=['Blinded','Charmed','Deafened','Frightened','Grappled','Incapacitated','Invisible','Paralyzed','Petrified','Poisoned','Prone','Restrained','Stunned','Unconscious'];return panel(`${icon('shield')} Conditions & Concentration`,`<label class="field-label" for="concentration">CURRENT CONCENTRATION</label><select id="concentration" data-change="concentration"><option value="">Not concentrating</option>${[...new Set(['Hunter’s Mark','Bless','Shield of Faith','Phantasmal Force','Other effect',...(r.concentration?[r.concentration]:[])])].map(n=>`<option ${r.concentration===n?'selected':''} value="${attr(n)}">${escapeHtml(n)}</option>`).join('')}</select>${r.lastConcentrationDC!==null?`<div class="check-alert">Concentration reminder: DC <strong>${r.lastConcentrationDC}</strong> Constitution save after the last damage. Your Constitution save modifier is ${fmt(C.derived(s.character,s.inventory,s.resources).saves.con+(s.character.templateKind==='starter'?0:C.mod(s.character.scores.cha)))}. The app does not roll or drop concentration for you.</div>`:''}<div class="inspiration-death"><div class="inspiration-row"><strong>Heroic Inspiration</strong><button class="btn secondary" data-action="inspiration-toggle" aria-pressed="${r.heroicInspiration?'true':'false'}">${r.heroicInspiration?'✦ Ready':'◇ Not held'}</button></div><div class="death-saves"><strong>Death Saving Throws</strong><div class="death-track"><span>Successes</span>${[1,2,3].map(n=>`<button class="death-dot ${r.deathSuccess>=n?'filled':''}" data-action="death-check" data-key="deathSuccess" data-delta="${r.deathSuccess>=n?-1:1}" title="Toggle death save success ${n}" aria-label="Death save success ${n}" aria-pressed="${r.deathSuccess>=n}">◆</button>`).join('')}</div><div class="death-track"><span>Failures</span>${[1,2,3].map(n=>`<button class="death-dot failed ${r.deathFailure>=n?'filled':''}" data-action="death-check" data-key="deathFailure" data-delta="${r.deathFailure>=n?-1:1}" title="Toggle death save failure ${n}" aria-label="Death save failure ${n}" aria-pressed="${r.deathFailure>=n}">◆</button>`).join('')}</div><button class="text-action" data-action="death-reset">Reset death saves</button></div></div><div class="field-label condition-label">CONDITIONS</div><div class="condition-grid">${labels.map(x=>`<label class="condition-check"><input type="checkbox" data-change="condition" value="${x}" ${r.conditions.includes(x)?'checked':''}/><span>${x}</span></label>`).join('')}</div>${s.character.templateKind==='starter'?'':`<label class="field-label" for="element-type">AURA OF ELEMENTAL SHIELDING</label><select id="element-type" data-change="elemental">${['Acid','Cold','Fire','Lightning','Thunder'].map(x=>`<option ${r.elementalResistance===x?'selected':''}>${x}</option>`).join('')}</select><div class="micro-note">Record a selected resistance if this character has an applicable feature.</div>`}`,'<span class="subtle-mini">ONE CONCENTRATION SPELL</span>');}
function sheetView(s,d,ui){return `<div class="page-heading"><div><span class="eyebrow">I. THE CHARACTER</span><h2>The Character Sheet</h2><p>Familiar numbers, exactly where you expect them.</p></div><div class="sheet-layout-actions">${ui.layoutMode?`<span class="layout-edit-hint">Arrange your panels below</span><button class="btn secondary" data-action="layout-reset">Restore default</button><button class="btn secondary" data-action="layout-cancel">Cancel</button><button class="btn primary" data-action="layout-save">Save layout</button>`:`<button class="btn secondary" data-action="layout-edit">${icon('settings')} Edit layout</button>`}</div></div>${ui.layoutMode?`<div class="layout-instructions" role="status">Drag a panel by its handle to another slot, or use its arrow buttons. Changes apply only when you choose <strong>Save layout</strong>.</div>`:''}${s.character.templateKind==='starter'?root.FolioBuilderUI.progression(s):''}<div class="sheet-grid"><div class="sheet-left">${abilityCard(s,d,ui)}${savesCard(s,d)}</div><div class="sheet-middle">${skillsCard(s,d)}${conditionsCard(s)}</div><div class="sheet-right">${attacksCard(s,d)}${resourcesCard(s)}${featureCard(s)}</div></div>`;}
function noteCard(n,i,total,s){return `<article class="note-card ${n.pinned?'pinned':''}"><div class="note-top"><div class="note-ordinal">${String(i+1).padStart(2,'0')}</div><div class="note-text"><h3>${escapeHtml(n.title)}${n.pinned?'<span class="pin-indicator" title="Pinned">✦</span>':''}</h3><p>${area(n.text)}</p><div class="note-links">${n.links.map(id=>{const x=root.PipSpells.spell(id,s.spellbook)||root.PipCharacter.featureList(s.character).find(x=>x.id===id)||s.inventory?.items.find(x=>x.id===id);return x?`<button class="reference-chip" data-action="reference" data-id="${id}">${icon('book')}${escapeHtml(x.name)}</button>`:'';}).join('')}</div></div></div><div class="note-controls"><button class="tiny-action" data-action="note-pin" data-id="${attr(n.id)}" title="${n.pinned?'Unpin':'Pin'} this play">${n.pinned?'Unpin':'Pin'}</button><button class="tiny-action" data-action="note-up" data-id="${attr(n.id)}" aria-label="Move ${attr(n.title)} up" ${i===0?'disabled':''}>↑</button><button class="tiny-action" data-action="note-down" data-id="${attr(n.id)}" aria-label="Move ${attr(n.title)} down" ${i===total-1?'disabled':''}>↓</button><button class="tiny-action" data-action="note-edit" data-id="${attr(n.id)}">Edit</button><button class="tiny-action delete-action" data-action="note-delete" data-id="${attr(n.id)}">Delete</button></div></article>`;}
function encounterCard(s,d){const e=s.encounter;if(!e.active)return `<div class="empty-encounter"><div class="encounter-art">◇</div><h3>No initiative is running</h3><p>Your plays and character HP stay available. Start an encounter when initiative is called.</p><p>Roll initiative with your physical dice and enter the total. This tracker is optional; your character sheet works without it.</p><label class="builder-field">Your initiative total<input id="encounter-initiative-total" type="number" min="-30" max="150" value="${d.initiative}" inputmode="numeric"></label><button class="btn primary" data-action="encounter-start">Record initiative & start optional tracker</button><div class="build-help"><label><input id="encounter-surprised" type="checkbox"> Surprised? Only relevant for optional digital rolls.</label><button class="btn secondary" data-action="encounter-roll-digital">Optional: roll initiative digitally</button></div></div>`;
return `<div class="encounter-top"><div><span class="eyebrow">INITIATIVE TRACKER</span><strong>ROUND ${e.round}</strong></div><button class="text-action" data-action="encounter-end">End encounter</button></div><div class="roster">${e.roster.map((actor,i)=>`<div class="combatant ${e.currentId===actor.id?'current':''}"><div class="actor-seal">${actor.isPip?'✦':'◇'}</div><div class="actor-name">${escapeHtml(actor.name)}${actor.isPip?'<small>Your character</small>':''}</div><label class="sr-only" for="actor-${attr(actor.id)}">Initiative for ${attr(actor.name)}</label><input id="actor-${attr(actor.id)}" class="initiative-input" type="number" data-change="actor-score" data-id="${attr(actor.id)}" value="${actor.initiative}" aria-label="${attr(actor.name)} initiative"/><div class="tie-buttons"><button data-action="tie-up" data-id="${attr(actor.id)}" aria-label="Move ${attr(actor.name)} before tied actor" ${i===0||e.roster[i-1].initiative!==actor.initiative?'disabled':''}>↑</button><button data-action="tie-down" data-id="${attr(actor.id)}" aria-label="Move ${attr(actor.name)} after tied actor" ${i===e.roster.length-1||e.roster[i+1].initiative!==actor.initiative?'disabled':''}>↓</button></div><button class="remove-actor" data-action="actor-remove" data-id="${attr(actor.id)}" aria-label="Remove ${attr(actor.name)}">×</button></div>`).join('')}</div><button class="roll-initiative" data-action="roll-init">${icon('dice')} Optional digital initiative roll (${root.FolioClassMechanics?.champion(s.character)?'2d20 Advantage':'d20'} ${fmt(d.initiative)})</button><form id="add-actor" class="add-actor-form"><label class="sr-only" for="actor-name">Combatant name</label><input id="actor-name" name="name" placeholder="Combatant name" required maxlength="40"/><label class="sr-only" for="actor-init">Initiative total</label><input id="actor-init" name="initiative" type="number" placeholder="Init" required value="10"/><button class="btn secondary" type="submit">Add</button></form><button class="btn primary turn-button" data-action="next-turn">${e.currentId?'Next turn →':'Begin turns →'}</button><div class="initiative-footer"><span>${e.currentId?`Current: ${escapeHtml(e.roster.find(x=>x.id===e.currentId)?.name||'—')}`:'Set scores and resolve ties before beginning'}</span><button class="link-button" data-action="undo">Undo</button></div>`;}
function combatView(s,d){const notes=[...s.notes.filter(x=>x.pinned),...s.notes.filter(x=>!x.pinned)];return `<div class="page-heading"><div><span class="eyebrow">II. THE REHEARSAL</span><h2>Combat Playbook</h2><p>Track your own character during in-person play. Physical dice and DM rulings come first; initiative tracking is optional.</p></div></div><div class="combat-grid"><section class="folio-panel playbook-panel"><div class="panel-heading"><span class="panel-title">${icon('book')} Setup Notes</span><button class="text-action note-add-inline" data-action="note-new">+ Add a play</button></div><div class="playbook-note">Pin, edit, reorder, or add your own plays. No attack sequencer.</div><div class="notes-list">${notes.map((n,i)=>noteCard(n,i,notes.length,s)).join('')||'<div class="empty-small">No plays yet. Add a play above.</div>'}</div></section><div class="combat-aside">${panel(`${icon('sword')} Initiative & Rounds`,encounterCard(s,d),'','initiative-panel')}${conditionsCard(s)}${s.character.templateKind==='starter'?panel(`${icon('spark')} Quick Resources`,root.FolioBuilderUI.slotTracker(s)+root.FolioBuilderUI.classTracker(s)+root.PipCharacterUI.inlineResources(s)):panel(`${icon('spark')} Quick Resources`,resourceRow('Channel Divinity','channelDivinity',s.resources,root.PipCharacter.resourceCaps(s.character.level).channelDivinity)+resourceRow('Lay on Hands','layOnHands',s.resources,root.PipCharacter.resourceCaps(s.character.level).layOnHands)+resourceRow('1st-level slots','slots1',s.resources,root.PipCharacter.resourceCaps(s.character.level).slots1)+resourceRow('2nd-level slots','slots2',s.resources,root.PipCharacter.resourceCaps(s.character.level).slots2)+root.PipCharacterUI.inlineResources(s))}</div></div>`;}
function spellbookView(s,ui){if(s.character.templateKind==='starter')return root.FolioRulesUI.spellbookView(s,ui);
 const b=s.spellbook,P=root.PipSpells;
 const groups=[['Prepared Paladin',b.prepared],['Always prepared · Paladin',['divine-smite','find-steed']],['Always prepared · Noble Genies',['elementalism','chromatic-orb','thunderous-smite','mirror-image','phantasmal-force']],['Always prepared · Fey-Touched',['hunters-mark','misty-step']]];
 if(b.custom.length)groups.push(['Custom & item-granted',b.custom.filter(x=>x.alwaysPrepared).map(x=>x.id)]);
 return root.FolioSpellOrganizerUI.render(s,ui,groups,'Spellbook',`${b.prepared.length} prepared Paladin spells · ${P.grants.length} always prepared${b.custom.length?' · '+b.custom.length+' custom':''}`,'Change preparations')+(b.queued.length?`<div class="queued-banner"><strong>${b.queued.length} planned replacement${b.queued.length===1?'':'s'}</strong><span>One change takes effect after each Long Rest.</span><button class="btn secondary" data-action="open-prep">Review plan</button></div>`:'');
}
function preparationView(s,ui){return root.FolioRulesUI.preparationView(s,ui);}
function castModal(s,id){if(s.character.templateKind==='starter')return root.FolioRulesUI.catalogCastModal(s,id);const P=root.PipSpells,b=s.spellbook,sp=P.spell(id,b),choices=P.castOptions(id,b,s.resources);if(!sp)return '';
 const current=s.resources.concentration||'None';const future=sp.concentration?sp.name:current;
 return `<div class="modal-scrim" data-action="close-modal"><section class="dialog form-dialog cast-dialog" role="dialog" aria-modal="true" aria-labelledby="cast-title"><button class="close-modal" data-action="close-modal" aria-label="Close casting">×</button><span class="eyebrow">RECORD A CAST</span><h2 id="cast-title">${escapeHtml(sp.name)}</h2><p>${escapeHtml(sp.short)}</p><div class="cast-preview"><div><small>CURRENT CONCENTRATION</small><strong>${escapeHtml(current)}</strong></div><div><small>AFTER CASTING</small><strong>${escapeHtml(future)}</strong></div></div><form id="cast-form" data-id="${attr(id)}"><label for="cast-cost">Choose a legal casting cost</label><select name="cost" id="cast-cost" required>${choices.map(c=>`<option value="${attr(c.key)}">${escapeHtml(c.label)}</option>`).join('')}</select><div class="cast-pool" id="cast-cost-preview" aria-live="polite">${choices.length?'Select a cost to preview the remaining uses.':'No legal casting cost remains.'}</div><p>Confirmation records the selected slot or free use and any concentration change. Damage, targets, and other effects remain under your control. The 2024 rules allow only one spell slot expended per turn; this tracker does not enforce turn actions. Undo reverses the cast.</p><div class="dialog-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" ${choices.length?'':'disabled'}>Confirm cast</button></div></form></section></div>`;}
function customSpellModal(s){const maxLevel=s?.character?.templateKind==='starter'?9:2;return `<div class="modal-scrim" data-action="close-modal"><section class="dialog form-dialog" role="dialog" aria-modal="true" aria-labelledby="custom-title"><button class="close-modal" data-action="close-modal" aria-label="Close custom spell">×</button><span class="eyebrow">DM / CUSTOM SPELL</span><h2 id="custom-title">Add a spell</h2><p>For table-approved, item-granted, or homebrew spells. Custom entries remain separate from the bundled class catalogue.</p><form id="custom-form"><label>Name<input name="name" required maxlength="100" placeholder="Spell name"/></label><div class="editor-scores three"><label>Level<select name="level"><option value="0">Cantrip</option><option value="1" selected>1</option><option value="2">2</option>${maxLevel>=3?'<option value="3">3</option><option value="4">4</option><option value="5">5</option><option value="6">6</option><option value="7">7</option><option value="8">8</option><option value="9">9</option>':''}</select></label><label>Cast time<input name="time" required value="Action"/></label><label>Range<input name="range" required value="Self"/></label></div><label>Duration<input name="duration" value="Instant" required/></label><label>Components<input name="components" value="V, S"/></label><label>What it does<textarea name="short" rows="3" required maxlength="600"></textarea></label><label>Additional details<textarea name="detail" rows="3" maxlength="1400"></textarea></label><label class="note-editor-pin"><input type="checkbox" name="concentration"/> Requires concentration</label><label class="note-editor-pin"><input type="checkbox" name="ritual"/> Can be cast as a ritual</label><div class="dialog-footer"><button class="btn secondary" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Add spell</button></div></form></section></div>`;}
function inventoryView(){const inventory=[['Shortsword','Vex · one-handed finesse blade'],['Scimitar','Nick · light finesse blade'],['Dagger','Backup / thrown'],['Shortbow + 20 arrows','Ranged fallback'],['Holy symbol','Paladin spellcasting focus'],['Diamond (50+ GP)','Reusable material for Chromatic Orb'],['Thieves’ Tools','Proficient'],['Forgery Kit / Costume / Fine Clothes','Charlatan background'],['Explorer’s Pack','General supplies'],['Currency','11 GP']];return `<div class="page-heading"><div><span class="eyebrow">IV. THE INVENTORY</span><h2>Starting Inventory</h2><p>A quick view of starting equipment.</p></div><span class="status-chip">Reference-only</span></div>${panel(`${icon('bag')} Equipment`,inventory.map(([x,y])=>`<div class="inventory-row"><strong>${escapeHtml(x)}</strong><span>${escapeHtml(y)}</span></div>`).join(''))}<p class="page-footnote">Equipping items, editing quantities, attunement, charges, and currency transactions arrive in a later milestone.</p>`;}
function oldJournalView(){return `<div class="page-heading"><div><span class="eyebrow">V. THE MARGINALIA</span><h2>Journal</h2><p>Where your table rulings, observations, and secrets will live.</p></div><span class="status-chip">Planned milestone</span></div>${panel(`${icon('feather')} Journal & Table Rulings`, `<div class="journal-placeholder"><img src="assets/butterfly.svg" alt=""/><h3>A page waiting for an annotation</h3><p>Next milestones will let you attach a ruling to a specific spell or feature and search it here. For now, Combat setup notes are fully editable and locally saved.</p><button class="btn secondary" data-action="nav" data-tab="combat">Go to setup notes</button></div>`)}`;}
function spellRuleMarkup(source){
 // Interpret only inline emphasis after escaping the bundled source; never trust source HTML.
 return escapeHtml(source).replace(/\*\*_([^\n]+?)_\*\*/g,'<strong><em>$1</em></strong>')
  .replace(/\*\*([^\n]+?)\*\*/g,'<strong>$1</strong>')
  .replace(/\*([^*\n]+?)\*/g,'<em>$1</em>');
}
function referenceModal(id,s,d){
 const spell=root.PipSpells.spell(id,s.spellbook)||root.FolioSpellRules?.getSpell(id,s.spellbook),feature=root.PipCharacter.featureList(s.character).find(x=>x.id===id),item=s.inventory?.items.find(x=>x.id===id),weapon=item?.category==='weapon'?item:null;let body='',name='',eyebrow='';
 if(spell){const guide=root.PipGuides?.[id]||{};const audit=spell.origin==='catalog'&&!spell.referenceOnly?root.FolioSpellAudit?.get(id):null;name=spell.name;eyebrow=root.FolioSources?.displayName(spell.sourceId,spell.source)||spell.source||'Custom spell';
 const activeIds=s.character.templateKind==='starter'?root.FolioSpellRules.selectedIds(s.spellbook):root.PipSpells.activeSpells(s.spellbook);const access=root.PipSpells.isGranted(id)?'Always prepared':activeIds.includes(id)?(s.character.templateKind==='starter'?'Known / prepared':'Prepared / always prepared'):id.startsWith('custom-')?'Custom / table-approved':(spell.classes||[]).join(', ')+' spell list';
 const originFeat=root.FolioOrigin2024?.magicForSpell(s.character,spell.name)||'';const originSpell=originFeat?root.FolioOrigin2024.magicStats(s.character,originFeat):null;
 const effectiveDC=originSpell?.saveDC??d.spellDC,effectiveAttack=originSpell?.attackBonus??d.spellAttack;
 const resolution=(spell.resolution||'Automatic effect');const caster=s.character.name||'Character';const computed=/save/i.test(resolution)?` · ${caster} DC ${effectiveDC}`:/spell attack/i.test(resolution)?` · ${caster} attack ${fmt(effectiveAttack)}`:'';
 body=`<div class="reference-stats"><div><small>LEVEL / SCHOOL</small><strong>${spell.level===0?'Cantrip':'Level '+spell.level} · ${escapeHtml(spell.school||'Custom')}</strong></div><div><small>CASTING TIME</small><strong>${escapeHtml(spell.time)}</strong></div><div><small>RANGE / AREA</small><strong>${escapeHtml(spell.range)}</strong></div><div><small>DURATION</small><strong>${escapeHtml(spell.duration)}</strong></div></div><div class="reference-additional"><span>Components: ${escapeHtml(spell.components||'Not entered')}</span><span>${!spell.concentrationKnown&&spell.referenceOnly?'Concentration: verify in source':spell.concentration?'Concentration':'No concentration'}${spell.ritual?' · Ritual':''}</span><span>Access: ${escapeHtml(access)}</span><span>${originFeat?'Origin feat ('+escapeHtml(originFeat)+') · '+escapeHtml(originSpell.ability.toUpperCase()):'Character'} spell DC ${effectiveDC} · spell attack ${fmt(effectiveAttack)} (when applicable)</span></div>${spell.referenceOnly?`<div class="reference-rule-card spell-reference-only"><h3>Official spell reference · manual rules</h3><p>${escapeHtml(spell.detail||spell.short)}</p><dl class="spell-rules"><dt>Book / source</dt><dd>${escapeHtml(root.FolioSources?.displayName(spell.sourceId,spell.source)||spell.source)}${spell.legacyReference?' · Older content; verify current-rule compatibility':''}</dd><dt>Available to</dt><dd>${escapeHtml((spell.classes||[]).join(', ')||'See sourcebook')}</dd>${spell.accessNote?`<dt>Access / compatibility</dt><dd>${escapeHtml(spell.accessNote)}</dd>`:''}<dt>What Folio knows</dt><dd>Spell name, level, class lists, and any personal metadata explicitly entered.</dd><dt>Before casting</dt><dd>Check casting time, components, targeting, concentration, duration, saving throws, spell effects and upcasting in your source. Folio does not automate these.</dd></dl>${spell.sourceUrl?`<p class="source-line"><a href="${attr(spell.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open official spell index</a></p>`:''}</div>`:audit?`<div class="reference-rule-card spell-audit-summary"><h3>At the table</h3><div class="spell-audit-effect"><strong>What it does</strong><p>${escapeHtml(root.FolioSpellAudit.preview(spell.raw||spell))}</p></div><dl class="spell-rules"><dt>When to use</dt><dd>${escapeHtml(audit.use)}</dd><dt>Watch out</dt><dd>${escapeHtml(audit.watch)}</dd><dt>Resolution cue</dt><dd>${escapeHtml(root.FolioSpellAudit.resolve(spell.raw||spell))}</dd><dt>${spell.level===0?'Cantrip scaling':'Higher slots'}</dt><dd>${escapeHtml(spell.higherLevel||'No additional scaling is specified for this spell.')}</dd></dl><p class="spell-guidance-disclaimer">Tips are original play advice, not official rules. Read the complete spell text below for exact triggers, saves, targets, and exceptions.</p></div><details class="spell-source-details" open><summary>Full 2024 spell description</summary><div class="spell-source-body">${spellRuleMarkup(spell.detail||spell.short)}</div></details>`:`<div class="reference-rule-card"><h3>At the table</h3><p>${escapeHtml(spell.short)}</p><dl class="spell-rules"><dt>Target</dt><dd>${escapeHtml(guide.target||spell.range)}</dd><dt>Resolution</dt><dd>${escapeHtml(resolution+computed)}</dd><dt>Effect</dt><dd>${escapeHtml(guide.effect||spell.detail||spell.short)}</dd>${guide.upcast?`<dt>Higher slots</dt><dd>${escapeHtml(guide.upcast)}</dd>`:''}${guide.tip?`<dt>Remember</dt><dd>${escapeHtml(guide.tip)}</dd>`:''}${spell.higherLevel?`<dt>At higher levels</dt><dd>${escapeHtml(spell.higherLevel)}</dd>`:''}</dl></div>`}${(id==='elementalism'||spell.name==='Elementalism')?`<div class="elementalism-modes"><h3>Five ways to use Elementalism</h3><p>Action · 30 feet · V, S · Instantaneous. Choose one effect when casting; this cantrip does not directly deal damage.</p><dl><dt>Beckon Air</dt><dd>Stir a breeze through a 5-foot cube, rustling cloth and leaves or shutting an unattended open door or shutter.</dd><dt>Beckon Earth</dt><dd>Dust or sand a 5-foot-square surface, or write a single word in loose dirt or sand.</dd><dt>Beckon Fire</dt><dd>Create safe embers and colored, scented smoke in a 5-foot cube; light nearby candles, lamps or torches. The scent can linger for 1 minute.</dd><dt>Beckon Water</dt><dd>Make a mist that lightly dampens a 5-foot cube, or produce one cup of clean water that evaporates after 1 minute.</dd><dt>Sculpt Element</dt><dd>Shape up to a 1-foot cube of dirt, sand, fire, smoke, mist or water into a rough figure for 1 hour.</dd></dl><p class="source-line">PHB 24 rules · <a href="https://www.dndbeyond.com/spells/2618834-elementalism" target="_blank" rel="noopener noreferrer">Official Elementalism reference</a></p></div>`:''}${spell.aliases?.length?`<p class="source-line">Also listed as ${escapeHtml(spell.aliases.join(', '))} in the 2024 PHB. This is the same spell, not a second entry.</p>`:''}${spell.tags?.length?`<div class="spell-tags">${spell.tags.map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div>`:''}${spell.origin==='catalog'&&!spell.referenceOnly?`<p class="source-line">PHB 24 · ${escapeHtml((spell.classes||[]).join(', '))} list · <a href="https://www.dndbeyond.com/srd" target="_blank" rel="noopener noreferrer">Official 2024 rules</a></p>`:''}`;}
 else if(feature){name=feature.name;eyebrow=feature.group;body=`<h3>How to use</h3><p>${escapeHtml(feature.short)}</p><div class="feature-details">${area(feature.detail)}</div>`;}
 else if(weapon){const w=weapon.weapon||{},nums=root.PipInventory.weaponNumbers(weapon,s.character,d);name=weapon.name;eyebrow='Weapon · '+(w.properties||'');const masteryText=root.FolioWeaponCatalog?.masteryDescriptions?.[w.mastery]||'Check this weapon’s mastery and properties with your DM.';body=`<div class="reference-stats"><div><small>REACH / RANGE</small><strong>${escapeHtml(w.range)}</strong></div><div><small>DAMAGE</small><strong>${escapeHtml(w.damage)} ${fmt(nums.damage)} ${escapeHtml(w.type)}</strong></div><div><small>TO HIT</small><strong>${fmt(nums.attack)}${nums.proficient===false?' · not proficient':''}</strong></div><div><small>MASTERY</small><strong>${escapeHtml(w.mastery)}${w.mastered?' · selected':''}</strong></div></div><h3>How to use</h3><p>${escapeHtml(masteryText)}</p><p>${escapeHtml(weapon.notes||'')}</p><button class="btn secondary" data-action="item-edit" data-id="${attr(weapon.id)}">Edit weapon</button>${weapon.equipped?`<p class="build-help"><strong>Physical dice:</strong> use the To Hit and Damage information above and confirm the result with your DM. Nothing on this screen rolls dice automatically.</p><form id="manual-weapon-use-form" data-id="${attr(weapon.id)}" class="inperson-weapon-form"><label>How are you using it? <select name="mode">${root.FolioWeaponRules.modes(weapon).map(m=>`<option value="${attr(m.key)}">${escapeHtml(m.label)}</option>`).join('')}</select></label><small>Record ammunition or a thrown weapon, without rolling to hit, entering enemy AC, or deciding damage. Your DM handles the outcome.</small><button type="submit" class="btn primary">Record use · no dice</button></form><button class="btn secondary" data-action="weapon-attack" data-id="${attr(weapon.id)}">Optional digital roll</button>`:''}`;}
 else if(item){name=item.name;eyebrow='Equipment · '+(item.category||'Item');body=`<h3>Equipment notes</h3><p>${escapeHtml(item.notes||'No additional notes for this item.')}</p><p>Quantity: ${escapeHtml(item.quantity??1)} · ${item.equipped?'Equipped':'Stowed'}</p><button class="btn secondary" data-action="item-edit" data-id="${attr(item.id)}">Edit item</button>`;}
 else return '';
 const linkType=spell?'spell':feature?'feature':'item';
 return `<div class="modal-scrim" data-action="close-modal"><section class="dialog reference-dialog" role="dialog" aria-modal="true" aria-labelledby="ref-title"><button class="close-modal" data-action="close-modal" aria-label="Close reference">×</button><span class="eyebrow">${escapeHtml(eyebrow)}</span><h2 id="ref-title">${escapeHtml(name)}</h2>${body}<div class="dialog-footer"><button class="btn secondary" data-action="journal-new-linked" data-link="${attr(linkType+':'+id)}" data-title="${attr(name)}">+ Add journal note</button>${spell&&(s.character.templateKind==='starter'?root.FolioSpellRules.selectedIds(s.spellbook).includes(id)||(s.spellbook.custom||[]).some(x=>x.id===id&&x.alwaysPrepared):root.PipSpells.activeSpells(s.spellbook).includes(id))?`<button class="btn secondary" data-action="open-cast" data-id="${attr(id)}">Cast spell</button>`:''}<button class="btn primary" data-action="close-modal">Close</button></div></section></div>`;
}
function noteEditor(note,s){const editing=note&&note.id;const n=note||{title:'',text:'',links:[],pinned:false};return `<div class="modal-scrim" data-action="close-modal"><section class="dialog form-dialog" role="dialog" aria-modal="true" aria-labelledby="note-title"><button class="close-modal" data-action="close-modal" aria-label="Close editor">×</button><span class="eyebrow">THE PLAYBOOK</span><h2 id="note-title">${editing?'Edit play':'Add a play'}</h2><form id="note-form" data-id="${editing?attr(n.id):''}"><label for="note-name">Title</label><input id="note-name" name="title" required maxlength="90" value="${attr(n.title)}" placeholder="e.g. Protect the back line"/><label for="note-text">Short steps (one per line)</label><textarea id="note-text" name="text" rows="6" required maxlength="2400" placeholder="Turn 1: ...\nIf the enemy moves: ...">${escapeHtml(n.text)}</textarea><label class="note-editor-pin"><input name="pinned" type="checkbox" ${n.pinned?'checked':''}/> Pin this play to the top</label><div class="field-label">LINK RELEVANT REFERENCES (OPTIONAL)</div><div class="link-pickers">${[...root.PipSpells.all,...s.spellbook.custom,...root.PipCharacter.featureList(s.character),...(s.inventory?.items||[]).filter(x=>x.category==='weapon')].map(x=>`<label><input type="checkbox" name="links" value="${x.id}" ${n.links.includes(x.id)?'checked':''}/> ${escapeHtml(x.name)}</label>`).join('')}</div><div class="dialog-footer"><button class="btn secondary" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Save play</button></div></form></section></div>`;}
function characterEditor(s){return `<div class="modal-scrim" data-action="close-modal"><section class="dialog form-dialog" role="dialog" aria-modal="true" aria-labelledby="edit-title"><button class="close-modal" data-action="close-modal" aria-label="Close editor">×</button><span class="eyebrow">EDIT MODE · AWAY FROM COMBAT CONTROLS</span><h2 id="edit-title">Edit character’s basic values</h2><p>Change a value and save to recalculate related bonuses.</p><form id="character-form"><div class="editor-scores">${Object.entries(s.character.scores).map(([k,v])=>`<label>${k.toUpperCase()}<input name="${k}" type="number" min="1" max="30" required value="${v}"/></label>`).join('')}</div><div class="editor-scores three"><label>Level<input name="level" type="number" min="1" max="20" required value="${s.character.level}"/></label><label>Max HP<input name="maxHp" type="number" min="1" max="999" required value="${s.resources.maxHp}"/></label><label>Speed (ft)<input name="speed" type="number" min="0" max="300" required value="${s.character.speed}"/></label></div><p class="editor-alert">Ability scores can also be changed directly on the Sheet. Spell preparations are managed in the Spellbook.</p><div class="dialog-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Apply changes</button></div></form></section></div>`;}
function backupModal(){return `<div class="modal-scrim" data-action="close-modal"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="backup-title"><button class="close-modal" data-action="close-modal" aria-label="Close backup">×</button><span class="eyebrow">LOCAL DATA · PRIVATE BY DEFAULT</span><h2 id="backup-title">Your saves belong to you</h2><p>The app automatically saves in this browser on this device. Export a JSON backup before clearing browser data or moving to another device.</p><button class="btn primary" data-action="export-backup">Export JSON backup</button> <button class="btn secondary" data-action="print">Print character sheet</button><label class="import-label">Restore a previous backup <input type="file" id="backup-file" accept="application/json,.json"/></label><p class="editor-alert">Restoring replaces the current sheet, notes and initiative. Your current browser data is not sent anywhere.</p></section></div>`;}
function mathModal(type,s,d){const scores=s.character.scores,body={ac:`${d.armorDescription}${d.bonuses.ac?' + item bonus '+fmt(d.bonuses.ac):''} = ${d.ac}.`,initiative:`Dexterity ${scores.dex} gives ${fmt(d.initiative)}.`,pb:`Level ${s.character.level} grants proficiency bonus ${fmt(d.pb)}.`,dc:`8 base + ${d.pb} proficiency + ${C.mod(scores[s.character.templateKind==='starter'?(s.character.build?.spellAbility||'cha'):'cha'])} ${(s.character.templateKind==='starter'?(s.character.build?.spellAbility||'cha'):'cha').toUpperCase()} = ${d.spellDC}.`};const title={ac:'Armor Class',initiative:'Initiative',pb:'Proficiency Bonus',dc:'Spell Save DC'};if(scores[type]){title[type]=type.toUpperCase()+' modifier';body[type]=`Ability ${scores[type]}: floor((${scores[type]} − 10) / 2) = ${fmt(C.mod(scores[type]))}.`;}return `<div class="modal-scrim" data-action="close-modal"><section class="dialog reference-dialog" role="dialog" aria-modal="true" aria-labelledby="math-title"><button class="close-modal" data-action="close-modal" aria-label="Close explanation">×</button><span class="eyebrow">WHY THAT NUMBER?</span><h2 id="math-title">${title[type]||'Calculation'}</h2><p>${s.character.overrides&&Number.isInteger(s.character.overrides[type])?'Manual override set to '+s.character.overrides[type]+'. Clear it in Character Editor to restore the calculated number.':body[type]||'Derived from this character’s data.'}</p><div class="dialog-footer"><button class="btn primary" data-action="close-modal">Done</button></div></section></div>`;}
function concentrationModal(reminder){
 if(!reminder)return '';
 const name=escapeHtml(reminder.spell),dc=Number(reminder.dc),modifier=Number(reminder.save),amount=Number(reminder.damage);
 return `<div class="modal-scrim concentration-scrim" data-action="concentration-later"><section class="dialog concentration-dialog" role="dialog" aria-modal="true" aria-labelledby="concentration-title" aria-describedby="concentration-summary"><div class="concentration-kicker">${icon('spark')} HOLD YOUR FOCUS</div><h2 id="concentration-title">Concentration Check</h2><p id="concentration-summary">You took <strong>${amount}</strong> damage while concentrating on <strong>${name}</strong>.</p><div class="concentration-stats"><div><span>CONSTITUTION SAVE</span><strong>DC ${dc}</strong></div><div><span>YOUR MODIFIER</span><strong>${fmt(modifier)}</strong></div></div><p class="concentration-explanation">Roll a Constitution saving throw. The DC is at least 10, half the damage taken (rounded down), or 30 at most. Temporary HP can absorb damage without preventing this check.</p><div class="concentration-actions"><button class="btn heal" data-action="concentration-pass">I passed</button><button class="btn danger" data-action="concentration-fail">I failed</button><button class="btn secondary" data-action="concentration-later">Check later</button></div></section></div>`;
}
function render(s,ui,historySize){const d=C.derived(s.character,s.inventory,s.resources);root.PipCurrentTab=ui.tab;const views={builder:()=>root.FolioBuilderUI.buildForm(root.FolioActiveLibrary||{campaigns:[],homebrew:[]},'edit',s.character),sheet:()=>sheetView(s,d,ui),combat:()=>combatView(s,d),spellbook:()=>ui.prepMode?preparationView(s,ui):spellbookView(s,ui),inventory:()=>root.PipInventoryUI.view(s,ui),features:()=>root.PipCharacterUI.features(s),editor:()=>root.PipCharacterUI.editor(s),journal:()=>root.PipJournalUI.journalView(s,ui),appearance:()=>root.FolioAppearanceUI.view(s,root.FolioActiveLibrary,ui.appearanceDraft),artwork:()=>root.FolioArtworkUI.view(s,ui.artworkDraft||root.FolioActiveArtwork)};let modal='';if(ui.modalType==='damage')modal=damageModal(s,ui);if(ui.modalType==='reference')modal=referenceModal(ui.modalId,s,d);if(ui.modalType==='spell-organize')modal=root.FolioSpellOrganizerUI.spellModal(s,ui.modalId);if(ui.modalType==='spell-collections')modal=root.FolioSpellOrganizerUI.collectionsModal(s);if(ui.modalType==='concentration-check')modal=concentrationModal(ui.concentrationReminder);if(ui.modalType==='note')modal=noteEditor(ui.draftNote,s);if(ui.modalType==='edit')modal=characterEditor(s);if(ui.modalType==='backup')modal=backupModal();if(ui.modalType==='math')modal=mathModal(ui.modalId,s,d);if(ui.modalType==='cast')modal=castModal(s,ui.modalId);if(ui.modalType==='custom')modal=customSpellModal(s);if(ui.modalType==='item')modal=root.PipInventoryUI.itemModal(s,ui.modalId);if(ui.modalType==='feature')modal=root.PipCharacterUI.featureModal(s,ui.modalId);if(ui.modalType==='custom-resource')modal=root.PipCharacterUI.resourceModal(s,ui.modalId);if(ui.modalType==='journal-edit')modal=root.PipJournalUI.entryForm(s,ui);if(ui.modalType==='journal-detail')modal=root.PipJournalUI.entryDetail(s,ui.modalId);if(ui.modalType==='weapon-catalog')modal=root.FolioRulesUI.weaponCatalogModal(s,ui);if(ui.modalType==='equipment-catalog')modal=root.PipInventoryUI.catalogModal(ui);if(ui.modalType==='weapon-attack')modal=root.FolioRulesUI.weaponAttackModal(s,ui.modalId);if(ui.modalType==='paladin-unarmed')modal=root.FolioRulesUI.paladinUnarmedModal(s);if(ui.modalType==='homebrew-spell')modal=root.FolioHomebrewBridge.modal(root.FolioActiveLibrary?.homebrew||[],'spell');if(ui.modalType==='homebrew-equipment')modal=root.FolioHomebrewBridge.modal(root.FolioActiveLibrary?.homebrew||[],'equipment');
return `<div class="site-shell">${topbar(ui.tab,historySize>0,s)}<div class="content-wrap"><div class="folio-head">${titleHeader(s)}</div>${vitals(s,d,ui)}<main id="main" tabindex="-1">${(views[ui.tab]||views.sheet)()}</main><footer class="site-footer"><span>✦ ${escapeHtml(s.character.name)} &nbsp; · &nbsp; THE FOLIO</span><span>Local-first · Milestone 18.16B · ${historySize} undo step${historySize===1?'':'s'}</span><button data-action="print" class="link-button" title="Print current character sheet, including from other tabs">Print character sheet</button></footer></div>${ui.notice?`<div class="toast" role="status">${escapeHtml(ui.notice)} <button aria-label="Dismiss message" data-action="dismiss-toast">×</button></div>`:''}${ui.roll?`<div class="roll-result" role="status">${icon('dice')} ${escapeHtml(ui.roll)} <button data-action="clear-roll" aria-label="Dismiss roll">×</button></div>`:''}${modal}<nav class="mobile-bottom-nav" aria-label="Mobile navigation">${nav(ui.tab)}</nav><button class="floating-die" data-action="dice" title="Open Quick Roll" aria-label="Open Quick Roll">${icon('dice')}<span>Roll</span></button>${root.FolioRulesUI.quickRollWindow(ui.quickRoll)}${root.PipRelease?root.PipRelease.printView(s,d):''}</div>`;}
root.PipUI={render,escapeHtml,referenceModal};
})(typeof window!=='undefined'?window:globalThis);
